import styled, { css, keyframes } from "styled-components";
import { useEffect, useState } from "react";

const typing = keyframes`
    0%, 100% {
        border-right: 1px solid rgb(240, 240, 240);
    }
    50% {
        border: none;
    }
`;

const TitleContainer = styled.h1`
    line-height: 1.2;
    display: flex;
    flex-direction: column;
    align-items: start;
    span {
        margin-right: 1rem;
    }
    span:first-child {
        animation: ${props => !props.$isTitle1 && css`${typing} 200ms infinite`};
    }
    span:last-child {
        animation: ${props => !props.$isTitle2 && css`${typing} 200ms infinite`};
    }
    @media all and (max-width:767px) and (orientation: portrait) {
        font-size: 30px;
        margin-top: 20px;
    }
    @media all and (max-height:767px) and (orientation: landscape) {
        font-size: 40px;
    }
    @media all and (min-width:768px) and (max-width:1370px) and (orientation: portrait) {
        font-size: 60px;
    }
    @media all and (min-height:768px) and (max-height:1370px) and (orientation: landscape) {
        font-size: 60px;
    }
    @media all and (min-width:1370px) {
        font-size: 80px;
    }    
`;

export default function Title({ titleData, titleStatus, setTitleStatus }) {
    const [title1, setTitle1] = useState("");
    const [title2, setTitle2] = useState("");
    const [title1End, setTitle1End] = useState(false);

    useEffect(() => {
            if (title1.length === 0) {
                typing1(titleData[0], 0);
            } else if (title1 === titleData[0] && !title1End) {
                setTitle1End(true);
                setTimeout(() => typing2(titleData[1], 0), 200);
            };
    
            if (title2 === titleData[1]) {
                setTitleStatus(true);
            };
    }, [title1, title2]);

    function typing1(mes, index) {
        setTitle1((prev) => prev + mes.charAt(index));
        setTimeout(() => typing1(mes, index + 1), 75);
    };
    function typing2(mes, index) {
        setTitle2((prev) => prev + mes.charAt(index));
        setTimeout(() => typing2(mes, index + 1), 75);
    };

    return (
        <>
        <TitleContainer $isTitle1={title1End} $isTitle2={titleStatus}>
            <span>{title1 && title1.toUpperCase()}</span>
            <span>{title2 && title2.toUpperCase()}</span>
        </TitleContainer>
        </>
    )
};