import { useRef, useState } from "react";
import * as CS from "../components/common/Container";
import Header from "../components/common/Header";
import AI from "../components/common/AI";
import Title from "../components/common/Title";
import { Content } from "../components/common/Container";
import styled, { css, keyframes } from "styled-components";
import Cursor from "../asset/cursor.png";

const SlideImgAni = keyframes`
    10% {
        top: 25px;
        left: calc(100% - 30px);
    }
    20% {
        top: 20px;
        left: calc(100% - 25px);
    }
    50% {
        top: 20px;
        left: 20px;
    }
    80% {
        top: 20px;
        left: 20px;
    }
    100% {
        top: 25px;
        left: calc(100% - 30px);
    }
`;

const SlideAriaAni = keyframes`
    0% {
    }
    10% {
        left: calc(100% - 50px);
    }
    20% {
        left: calc(100% - 50px);
        opacity: 1;
    }
    50% {
        left: 0;
        opacity: 1;
    }
    80% {
        left: 0;
        opacity: 0;
    }
    100% {
        left: calc(100% - 50px);
        opacity: 0;
    }
`;

const Guider = styled.div`
    position: absolute;
    width: 40%;
    height: 50px;
    top: 40%;
    left: 50%;
    transform: translate(-50%, -50%);
    transition: all 400ms;
    opacity: ${props => props.$status? 1 : 0};
    img {
        position: absolute;
        top: 25px;
        left: calc(100% - 30px);
        width: 60px;
        animation: ${props => props.$status && css`${SlideImgAni} 2s linear infinite forwards`};
    }
    div.touch_slide {
        width: 100%;
        height: 100%;
        border-radius: 40px;
        background: none;
        border: 4px solid rgba(200, 200, 200, 0.5);
    }
    div.touch_aria {
        position: absolute;
        background-color: rgba(250, 250, 250, 0.5);
        top: 0;
        left: calc(100% - 50px);
        width: 50px;
        height: 50px;
        border-radius: 50%;
        animation: ${props => props.$status && css`${SlideAriaAni} 2s linear infinite forwards`};
    }
    @media all and (max-width:767px) and (orientation: portrait) {
    }
    @media all and (max-height:767px) and (orientation: landscape) {
        width: 30%;
    }
    @media all and (min-width:768px) and (max-width:1370px) and (orientation: portrait) {
        width: 30%;
    }
    @media all and (min-height:768px) and (max-height:1370px) and (orientation: landscape) {
        width: 20%;
    }
    @media all and (min-width:1370px) {
        display: none;
    }  
`;

const titleData = ["chajuick", "portfolio"];

export default function Home() {
    const [titleStatus, setTitleStatus] = useState(false);
    const nextRef = useRef(null);
    const prevRef = useRef(null);
    const sideRef = useRef(null);

    return (
        <>
            <CS.Container className="greetings">
                <CS.Screen>
                    <Header 
                        text='greetings' 
                        titleStatus={titleStatus}  
                        nextRef={nextRef}
                        prevRef={prevRef}
                        sideRef={sideRef}
                        nextLink='/intro'
                        prevLink='/'
                    />
                    <Content>
                        <AI 
                            titleStatus={titleStatus} 
                            mes="hello?"
                            nextRef={nextRef}
                            prevRef={prevRef}
                            sideRef={sideRef}
                        />
                        <Title 
                            titleData={titleData} 
                            titleStatus={titleStatus} 
                            setTitleStatus={setTitleStatus}
                        />
                    </Content>
                    <Guider $status={titleStatus}>
                        <div className="touch_slide"></div>
                        <div className="touch_aria"></div>
                        <img src={Cursor} alt="Slide Please" className="slide_pointer"/>
                    </Guider>
                </CS.Screen>
            </CS.Container>
        </>
    )
};