import { useRef, useState, useEffect } from "react";
import styled from "styled-components";
import * as CS from "../../components/gallery/GalleryStyle";
import GalleryHeader from "../../components/gallery/GalleryHeader"

const JSContent = styled.div`
    width: calc(96vw - 2px);
    height: 90vh;
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
`;

const CalcContainer = styled.div`
    width: 400px;
    height: 400px;
    color: rgb(230, 230, 230);
    box-shadow: 0px 4px 8px black;
    border-radius: 8px;
    display: grid;
    grid-gap: 10px;
	gap: 10px;
    grid-template-columns: repeat(4, 1fr);
    grid-template-rows: repeat(7, 1fr);
    background-color: rgb(250, 250, 250);
    padding: 10px;
    input.screen {
        grid-column-start: 1;
        grid-column-end: 5;
        font-family: 'DG';
        font-size: 32px;
        text-align: right;
        padding: 0 5px;
    }
    input.btn {
        text-align: center;
        border-radius: 4px;
        margin: 0.3rem 0;
        background-color: rgb(245, 245, 245);
        border: none;
        box-shadow: 0 2px 2px black;
        color: rgb(114, 114, 114);
        font-size: 16px;
        transition: all 400ms;
        cursor: pointer;
    }
    input.btn:hover {
        background-color: rgb(220, 220, 220);
        box-shadow: 0 1px 2px black;
    }
    input.btn:active {
        background-color: rgb(180, 180, 180);
        box-shadow: 0 0 1px black;
    }
    @media all and (max-width:767px) and (orientation: portrait) {
        width: 200px;
        height: 300px;
        input.screen {
            font-size: 24px;
        }
        input.btn {
            font-size: 12px;
        }
    }
    @media all and (max-height:767px) and (orientation: landscape) {
        width: 200px;
        height: 200px;
        padding: 5px;
        grid-gap: 5px;
        gap: 5px;
        input.screen {
            font-size: 20px;
        }
        input.btn {
            border-radius: 2px;
            font-size: 10px;
        }
    }
`;

export default function Calculator() {
    const prevRef = useRef(null);
    const contentRef = useRef(null);
    useEffect(() => {
        const CalScreenNow = document.getElementById("screen_now");
        const CalScreenBefore = document.getElementById("screen_before");
        const Calbtn = document.querySelectorAll(".btn");
        const CalNumReg = /^[0-9]*$/;
        let Operatior;
        let temp;

        const handleClickBtns = (item) => {
            if(CalNumReg.test(item.target.value) === true){
                if(CalScreenNow.value === '0'){
                  CalScreenNow.value = item.target.value;
                } else {
                  CalScreenNow.value += item.target.value;
                }
            } else if(item.target.value === "."){
                if(CalScreenNow.value.indexOf(".") === -1){
                  CalScreenNow.value += item.target.value;
                } 
            } else if(item.target.value === "CE"){
                CalScreenNow.value = "0";
            } else if(item.target.value === "C"){
                CalScreenNow.value = "0";
                CalScreenBefore.value = "";
                Operatior = "";
            } else if(item.target.value === "%"){
                if (CalScreenNow.value !== "0") {
                    ContinueCalc("per");
                    Operatior = "per";
                }
            } else if(item.target.value === "/"){
                if (CalScreenNow.value !== "0") {
                    ContinueCalc("div");
                    Operatior = "div";
                }
            } else if(item.target.value === "x"){
                if (CalScreenNow.value !== "0") {
                    ContinueCalc("mul");
                    Operatior = "mul";
                }
            } else if(item.target.value === "-"){
                if (CalScreenNow.value !== "0") {
                    ContinueCalc("sub");
                    Operatior = "sub";
                }
            } else if(item.target.value === "+"){
                if (CalScreenNow.value !== "0") {
                    ContinueCalc("plus");
                    Operatior = "plus";
                }
            } else if(item.target.value === "="){
                if(Operatior === "per"){
                  temp = CalScreenBefore.value;
                  CalScreenBefore.value = temp + CalScreenNow.value + " = ";
                  CalScreenNow.value = parseFloat(extractNumber(temp)) % parseFloat(CalScreenNow.value);
                } else if(Operatior === "div"){
                  temp = CalScreenBefore.value;
                  CalScreenBefore.value = temp + CalScreenNow.value + " = ";
                  CalScreenNow.value = parseFloat(extractNumber(temp)) / parseFloat(CalScreenNow.value);
                } else if(Operatior === "mul"){
                  temp = CalScreenBefore.value;
                  CalScreenBefore.value = temp + CalScreenNow.value + " = ";
                  CalScreenNow.value = parseFloat(extractNumber(temp)) * parseFloat(CalScreenNow.value);
                } else if(Operatior === "sub"){
                  temp = CalScreenBefore.value;
                  CalScreenBefore.value = temp + CalScreenNow.value + " = ";
                  CalScreenNow.value = parseFloat(extractNumber(temp)) - parseFloat(CalScreenNow.value);
                } else if(Operatior === "plus"){
                  temp = CalScreenBefore.value;
                  CalScreenBefore.value = temp + CalScreenNow.value + " = ";
                  CalScreenNow.value = parseFloat(extractNumber(temp)) + parseFloat(CalScreenNow.value);
                } 
            }
        }

        function ContinueCalc(type) {
            if (CalScreenBefore.value.length <= 0) {
                if(type === "per"){
                    CalScreenBefore.value = CalScreenNow.value + " % ";
                } else if(type === "div"){
                    CalScreenBefore.value = CalScreenNow.value + " ÷ ";
                } else if(type === "mul"){
                    CalScreenBefore.value = CalScreenNow.value + " x ";
                } else if(type === "sub"){
                    CalScreenBefore.value = CalScreenNow.value + " - ";
                } else if(type === "plus"){
                    CalScreenBefore.value = CalScreenNow.value + " + ";
                } else {
                    CalScreenBefore.value = CalScreenNow.value;
                }
            } else {
                if (CalScreenBefore.value.indexOf("=") === -1) {
                    if(type === "per"){
                        CalScreenBefore.value = parseFloat(extractNumber(CalScreenBefore.value)) % parseFloat(CalScreenNow.value) + " % ";
                    } else if(type === "div"){
                        CalScreenBefore.value = parseFloat(extractNumber(CalScreenBefore.value)) / parseFloat(CalScreenNow.value) + " ÷ ";
                    } else if(type === "mul"){
                        CalScreenBefore.value = parseFloat(extractNumber(CalScreenBefore.value)) * parseFloat(CalScreenNow.value) + " x ";
                    } else if(type === "sub"){
                        CalScreenBefore.value = parseFloat(extractNumber(CalScreenBefore.value)) - parseFloat(CalScreenNow.value) + " - ";
                    } else if(type === "plus"){
                        CalScreenBefore.value = parseFloat(extractNumber(CalScreenBefore.value)) + parseFloat(CalScreenNow.value) + " + ";
                    } else {
                        CalScreenBefore.value = CalScreenNow.value;
                    }
                } else {
                    if(type === "per"){
                        CalScreenBefore.value = CalScreenNow.value + " % ";
                    } else if(type === "div"){
                        CalScreenBefore.value = CalScreenNow.value + " ÷ ";
                    } else if(type === "mul"){
                        CalScreenBefore.value = CalScreenNow.value + " x ";
                    } else if(type === "sub"){
                        CalScreenBefore.value = CalScreenNow.value + " - ";
                    } else if(type === "plus"){
                        CalScreenBefore.value = CalScreenNow.value + " + ";
                    } else {
                        CalScreenBefore.value = CalScreenNow.value;
                    }
                }
            }
            CalScreenNow.value = "0";
        };

        const extractNumber = (str) => {
            const match = str.match(/[\d.]+/);
            return match ? match[0] : null;
        };
          

        if (Calbtn) {
            Calbtn.forEach((item) => item.addEventListener('click', handleClickBtns));
        }
    
        return () => {
            if (Calbtn) {
                Calbtn.forEach((item) => item.removeEventListener('click', handleClickBtns));
            }
        };
    }, []);

    return (
        <>
            <CS.Container className="siru_wire_frame">
                <CS.Screen>
                    <GalleryHeader
                        text='calculator.exe'
                        prevRef={prevRef}
                        titleRef={contentRef}
                    />
                    <JSContent ref={contentRef}>
                        <form name="Calculator" action="" method="post">
                            <CalcContainer id="calc_container">
                                <input id="screen_before" className="screen" disabled/>
                                <input id="screen_now" className="screen" value="0" disabled/>
                                <input type="button" className="btn" value="%"/>
                                <input type="button" className="btn" value="CE"/>
                                <input type="button" className="btn" value="C"/>
                                <input type="button" className="btn" value="/"/>
                                <input type="button" className="btn" value="7"/>
                                <input type="button" className="btn" value="8"/>
                                <input type="button" className="btn" value="9"/>
                                <input type="button" className="btn" value="x"/>
                                <input type="button" className="btn" value="4"/>
                                <input type="button" className="btn" value="5"/>
                                <input type="button" className="btn" value="6"/>
                                <input type="button" className="btn" value="-"/>
                                <input type="button" className="btn" value="1"/>
                                <input type="button" className="btn" value="2"/>
                                <input type="button" className="btn" value="3"/>
                                <input type="button" className="btn" value="+"/>
                                <input type="button" className="btn" value=" "/>
                                <input type="button" className="btn" value="0"/>
                                <input type="button" className="btn" value="."/>
                                <input type="button" className="btn" value="="/>
                            </CalcContainer>
                        </form>
                    </JSContent>
                </CS.Screen>
            </CS.Container>
        </>
    )
};