export default function GalleryHeader({ text, titleRef }) {
    const navigate = useNavigate();
    const [fadeOut, setFadeOut] = useState(false);
    const [fadeIn, setFadeIn] = useState(false);
    const [sideShow, setSideShow] = useState(false);

    // 뒤로가기
    useEffect(() => {
        if (titleRef) {
            const titleElement = titleRef.current;

            let touchStartX;
            let touchStartT;
    
            function handleTouchStart(e) {
                touchStartX = e.touches[0].clientX;
                touchStartT = e.timeStamp;
            }
    
            function handleTouchEnd(e) {
                const touchEndX = e.changedTouches[0].clientX;
                const touchEndT = e.timeStamp;
                const swipeDistance = touchEndX - touchStartX;
                const swipeTime = touchEndT - touchStartT;
                // 일정 거리와 시간 이하로 움직였을 때 스와이프로 판단
                if (Math.abs(swipeDistance) > 50 && swipeTime < 1000) {
                    if (swipeDistance < 0) {
                        handleLink();
                    } 
                }
            };
    
            if (titleElement) {
                titleElement.addEventListener("touchstart", handleTouchStart);
                titleElement.addEventListener("touchend", handleTouchEnd);
            } 
            return () => {
                if (titleElement) {
                    titleElement.removeEventListener("touchstart", handleTouchStart);
                    titleElement.removeEventListener("touchend", handleTouchEnd);
                } 
            }
        }
    }, [titleRef]);

    function handleLink() {
        setFadeOut(true);
        setTimeout(() => {
            setFadeIn(true);
        }, 400);
        setTimeout(() => {
            navigate(`/gallery`);
        }, 800);
    };

    // 사이드바 관리
    const [galleryListView, setGalleryListView] = useState(false);
    const [galleryUIUXListView, setGalleryUIUXListView] = useState(false);
    const [galleryJSListView, setGalleryJSListView] = useState(false);
    const [galleryWEBListView, setGalleryWEBListView] = useState(false);

    function handelSideShow() {
        setSideShow(!sideShow);
    };

    return (
        <>
        <FadeOut className="fade_out" $fade={fadeOut} />
        <FadeIn className="fade_in" $fade={fadeIn} />
        <HeaderContainer>
            <Detail>
                <p>YEAR</p>
                <p>2025</p>
            </Detail>
            <Title>
                <p>{text.toUpperCase()}</p>
                <div className="nav_buttons">
                    <LinkBtn 
                        onClick={handleLink}
                    >
                        ←
                    </LinkBtn>
                    <FastLinkBtn
                        onClick={handelSideShow}
                    >
                        <Icon icon="healthicons:ui-menu-outline" />
                    </FastLinkBtn>
                </div>
            </Title>
            <FastLink
                $isShow={sideShow}
            >
                <li>
                    <Link to='/'>HOME</Link>
                </li>
                <li>
                    <Link to='/intro'>INTRO</Link>
                </li>
                <li 
                    onMouseEnter={() => setGalleryListView(true)}
                    onMouseLeave={() => setGalleryListView(false)}
                >
                    <Link to='/gallery'>GALLERY</Link>
                    <ul 
                        className="gallery_list"
                        style={{
                            maxHeight: galleryListView ? "1000px" : "0",
                            overflow: "hidden",
                            transition: "all 600ms",
                        }}
                    >
                        <li
                            onMouseEnter={() => setGalleryUIUXListView(true)}
                            onMouseLeave={() => setGalleryUIUXListView(false)}
                        >
                            <p>UI/UX</p>
                            <FastSmLink 
                                className="gallery_list_list"
                                $isShow={galleryUIUXListView}
                                style={{
                                    top: "33%"
                                }}
                            >
                                <li>
                                    <Link to='/gallery/siru'>SIRU</Link>
                                </li>
                                <li>
                                    <Link to='/gallery/im1l'>IM1L</Link>
                                </li>
                                <li>
                                    <Link to='/gallery/dokdo'>DOKDO</Link>
                                </li>
                            </FastSmLink>
                        </li>
                        <li
                            onMouseEnter={() => setGalleryJSListView(true)}
                            onMouseLeave={() => setGalleryJSListView(false)}
                        >
                            <p>JAVASCRIPT</p>
                            <FastSmLink 
                                className="gallery_list_list"
                                $isShow={galleryJSListView}
                                style={{
                                    top: "47%"
                                }}
                            >
                                <li>
                                    <Link to='/gallery/calculator'>CALCULATOR</Link>
                                </li>
                                <li>
                                    <Link to='/gallery/clock'>CLOCK</Link>
                                </li>
                                <li>
                                    <Link to='/gallery/todolist'>TODOLIST</Link>
                                </li>
                            </FastSmLink>
                        </li>
                        <li
                            onMouseEnter={() => setGalleryWEBListView(true)}
                            onMouseLeave={() => setGalleryWEBListView(false)}
                        >
                            <p>WEBPAGE</p>
                            <FastSmLink 
                                className="gallery_list_list"
                                $isShow={galleryWEBListView}
                                style={{
                                    top: "65%"
                                }}
                            >
                                <li>
                                    <Link to='/gallery/dwcinema'>DW-CINEMA</Link>
                                </li>
                                <li>
                                    <Link to='/gallery/dwtouch'>DW-TOUCH</Link>
                                </li>
                            </FastSmLink>
                        </li>
                    </ul>
                </li>                                
            </FastLink>
        </HeaderContainer>
        </>
    )
};

