const EyeBall = ({ $status, $ew, $eh }) => {
    const eyeBallSpring = useSpring({
      config: {
        precision: 0.001, // 숫자의 정밀도를 높여줌
      },
      to: async (next) => {
        await next({
          width: $status && $ew ? `${5 - Math.abs($ew)}%` : '5%',
          height: $status && $eh ? `${40 - Math.abs($eh)}%` : '40%',
          marginRight: $status && $ew && $ew > 0 ? `${$ew * 20}%` : '0%',
          marginLeft: $status && $ew && $ew < 0 ? `${Math.abs($ew) * 10}%` : '0%',
          marginBottom: $status && $eh && $eh > 0 ? `${$eh / 2}%` : '0%',
          marginTop: $status && $eh && $eh < 0 ? `${Math.abs($eh)}%` : '0%',
          backgroundColor: 'rgba(240, 240, 240, 1)',
        });
      },
    });
  
    return <animated.div style={{ ...eyeBallSpring }} />;
  };

