export default function AI({ titleStatus, mes, nextRef, prevRef, sideRef }) {
    // AI
    const [mousePosition, setMousePosition] = useState({ x: 0, y: 0});
    const [cursorStatus, setCursorStatus] = useState(false);
    const pointerRef = useRef(null);
    const moveTimer = useRef(null);
    const aiRef = useRef(null);
    const [eyeWidth, setEyeWidth] = useState(100);
    const [eyeHeight, setEyeHeight] = useState(100);

    useEffect(() => {
        const handlePointer = (e) => {
            const eventX = e.touches ? e.touches[0].clientX : e.clientX;
            const eventY = e.touches ? e.touches[0].clientY : e.clientY;
            if (pointerRef && pointerRef.current) {
                setMousePosition({ x: eventX - pointerRef.current.offsetWidth/2, y: eventY - pointerRef.current.offsetHeight/2});
            }
            if (pointerRef && pointerRef.current && aiRef && aiRef.current) {
                setCursorStatus(true);
                clearTimeout(moveTimer.current);
                moveTimer.current = setTimeout(() => setCursorStatus(false), 5000);
                const eh = (20 * (aiRef.current.offsetTop - pointerRef.current.offsetTop)) / aiRef.current.offsetTop;
                const ew = (aiRef.current.offsetLeft + aiRef.current.offsetWidth / 2 - pointerRef.current.offsetLeft) / (aiRef.current.offsetLeft + aiRef.current.offsetWidth * 5 / 2);
                setEyeHeight(eh);
                setEyeWidth(ew);
            };
        };

        window.addEventListener("mousemove", handlePointer);
        window.addEventListener("touchmove", handlePointer);
        return () => {
            window.removeEventListener("mousemove", handlePointer);
            window.removeEventListener("touchmove", handlePointer);
        };
    }, [pointerRef]);

    const pointerProps = useSpring({
        to: { x: mousePosition.x, y: mousePosition.y },
        config: { tension: 200, friction: 20 },
    });

    // ai 상태관리
    const [activeAi, setActiveAi] = useState(false);
    const [aiStatus, setAiStatus] = useState(0); // 0: 대기, 1: 기본메시지 준비, 2: 기본메시지출력, 3: 기타메시지 출력
    const [chatStatus, setChatStatus] = useState(false);

    // ai 채팅관리
    const chatMessageTimeoutRef = useRef(null);
    const defaultChatTimer = useRef(null);
    const [chatMes, setChatMes] = useState("");

    useEffect(() => {
        if (aiStatus === 0 && titleStatus) {
            setAiStatus(1);
            clearTimeout(defaultChatTimer.current);
            defaultChatTimer.current = setTimeout(chatDefaultMes, 2000);
        }
        function chatDefaultMes() {
            if (aiStatus < 2) {
                setAiStatus(2);
                const message = mes.toUpperCase();
                setChatMes("");
                clearTimeout(chatMessageTimeoutRef.current);
                showChatMessage(message, 0);
                setActiveAi(true);
            }
        };
        function chatMes(type) {
            if (titleStatus) {
                if (type.length === 0) {
                    setAiStatus(1);
                    setChatMes("");
                    setChatStatus(false);
                    clearTimeout(chatMessageTimeoutRef.current);
                } else {
                    setAiStatus(3);
                    const message = type.toUpperCase();
                    setChatMes("");
                    clearTimeout(chatMessageTimeoutRef.current);
                    showChatMessage(message, 0);
                    setActiveAi(true);
                }
            }
        }

        if (nextRef && nextRef.current) {
            nextRef.current.addEventListener('mouseover', () => chatMes("next?"));
            nextRef.current.addEventListener('mouseleave', () => chatMes(""));
        }
        if (prevRef && prevRef.current) {
            prevRef.current.addEventListener('mouseover', () => chatMes("prev?"));
            prevRef.current.addEventListener('mouseleave', () => chatMes(""));
        }
        if (sideRef && sideRef.current) {
            sideRef.current.addEventListener('mouseover', () => chatMes("nav?"));
            sideRef.current.addEventListener('mouseleave', () => chatMes(""));
        }
        return () => {
            if (nextRef && nextRef.current) {
                nextRef.current.removeEventListener('mouseover', () => chatMes("next?"));
                nextRef.current.removeEventListener('mouseleave', () => chatMes(""));
            }
            if (prevRef && prevRef.current) {
                prevRef.current.removeEventListener('mouseover', () => chatMes("prev?"));
                prevRef.current.removeEventListener('mouseleave', () => chatMes(""));
            }
            if (sideRef && sideRef.current) {
                sideRef.current.removeEventListener('mouseover', () => chatMes("nav?"));
                sideRef.current.removeEventListener('mouseleave', () => chatMes(""));
            }
        }
    }, [titleStatus]);

    function showChatMessage(message, index) {
        if (index < message.length) {
            setChatMes((prev) => prev + message.charAt(index));
            chatMessageTimeoutRef.current = setTimeout(() => showChatMessage(message, index + 1), 100);
            setChatStatus(true);
        } else {
            setChatStatus(false);
        }
    };

    return (
        <>
        <MousePointer style={{ top: pointerProps.y, left: pointerProps.x }} ref={pointerRef} className="pointer"/>
        <AIFrame ref={aiRef} className="ai_frame">
            <AIBody className="ai_body"/>
            <AIface className="ai_face">
            <Eyes className="ai_eyes">
                <EyeBall $status={cursorStatus} $ew={eyeWidth} $eh={eyeHeight} className="ai_eye"/>
                <EyeBall $status={cursorStatus} $ew={eyeWidth} $eh={eyeHeight} className="ai_eye"/>
            </Eyes>
                <Mouth $ai={chatStatus} className="ai_mouth"/>
            </AIface>
            <AIchat className="ai_chat">
                {chatMes}
            </AIchat>
        </AIFrame>
        </>
    )
};