import { useRef, useState, useEffect } from "react";
import * as CS from "../../components/gallery/GalleryStyle";
import GalleryHeader from "../../components/gallery/GalleryHeader"
import GalleryWorkSection from "../../components/gallery/GalleryWorkSection";
import { Icon } from '@iconify/react';
import { Modal, ModalImgContent, Overlay } from "../../components/modal/modal";
// 이미지
import desktopIndex from "../../asset/works/dokdo/desktop_index.png";
import desktopGuide from "../../asset/works/dokdo/desktop_guide.png";
import desktopGreeting from "../../asset/works/dokdo/desktop_greeting.png";
import mobileIndex from "../../asset/works/dokdo/mobile_index.png";
import mobileGuide from "../../asset/works/dokdo/mobile_guide.png";
import mobileGreeting from "../../asset/works/dokdo/mobile_greeting.png";

const workImgs = [
    [
        {
            src: desktopIndex,
            alt: "Dokdo Desktop Design in Figma",
            title: "Dokdo Desktop IndexPage",
        },
        {
            src: desktopGuide,
            alt: "Dokdo Desktop Design in Figma",
            title: "Dokdo Desktop GuidePage",
        },
        {
            src: desktopGreeting,
            alt: "Dokdo Desktop Design in Figma",
            title: "Dokdo Desktop GreetingPage",
        },
    ],
    [
        {
            src: mobileIndex,
            alt: "Dokdo Mobile Design in Figma",
            title: "Dokdo Mobile IndexPage",
        },
        {
            src: mobileGuide,
            alt: "Dokdo Mobile Design in Figma",
            title: "Dokdo Mobile GuidePage",
        },
        {
            src: mobileGreeting,
            alt: "Dokdo Mobile Design in Figma",
            title: "Dokdo Mobile GreetingPage",
        },
    ],
];

const sectionData = [
    "In Desktop", "In mobile",
];

export default function DokdoWireFrame() {
    const [selectedSection, setSelectedSection] = useState(0);
    const [sectionX, setSectionX] = useState(0);
    const [showImgModal, setShowImgModal] = useState(false);
    const [modalContent, setModalContent] = useState({
        title: "",
        src: "",
        alt: "",
        indexNum: 0,
    });
    const [modalIndexNum, setModalIndexNum] = useState(0);
    const titleRef = useRef(null);

    // 줌
    const [zoomLevel, setZoomLevel] = useState(100);
    const zoomImgRef = useRef(null);
    const [zoomPoint, setZoomPoint] = useState({x: 0, y: 0});
    const [startPoint, setStartPoint] = useState({x: 0, y: 0});
    const [touchStatus, setTouchStatus] = useState(false);

    function handleZoomSet(type) {
        if (type === "+") {
            let updatedZoom = zoomLevel+10;
            if (updatedZoom <= 300) {
                setZoomLevel(updatedZoom);
            } else {
                setZoomLevel(300);
            }
        } else if (type === "-") {
            let updatedZoom = zoomLevel-10;
            if (updatedZoom >= 50) {
                setZoomLevel(updatedZoom);
            } else {
                setZoomLevel(50);
            }
        };
    };
    
    useEffect(() => {
        const zoomElement = zoomImgRef.current;

        function handleStart(e) {
            setStartPoint({
                x: e.touches ? e.touches[0].clientX : e.clientX,
                y: e.touches ? e.touches[0].clientY : e.clientY,
            });
            setTouchStatus(true);
        };

        function handleMove(e) {
            if (zoomElement && touchStatus) {
                const eventX = e.touches ? e.touches[0].clientX : e.clientX;
                const eventY = e.touches ? e.touches[0].clientY : e.clientY;
                const prevZoomPoint = {
                    x: zoomPoint.x,
                    y: zoomPoint.y,
                }
                setZoomPoint({
                    x: prevZoomPoint.x + (eventX - startPoint.x),
                    y: prevZoomPoint.y + (eventY - startPoint.y),
                });
            }
        }

        window.addEventListener("mouseup", () => setTouchStatus(false));
        window.addEventListener("touchend", () => setTouchStatus(false));
        if (zoomElement) {
            zoomElement.addEventListener("touchmove", handleMove);            
            zoomElement.addEventListener("mousemove", handleMove);            
            zoomElement.addEventListener("mousedown", handleStart);            
            zoomElement.addEventListener("touchstart", handleStart);            
        }
    
        return () => {
            window.removeEventListener("mouseup", () => setTouchStatus(false));
            window.removeEventListener("touchend", () => setTouchStatus(false));
            if (zoomElement) {
                zoomElement.removeEventListener("touchmove", handleMove);            
                zoomElement.removeEventListener("mousemove", handleMove);
                zoomElement.removeEventListener("mousedown", handleStart);            
                zoomElement.removeEventListener("touchstart", handleStart); 
            }
        };
    }, [touchStatus, startPoint]);

    function handleZoomScroll(e) {
        if (e.deltaY > 0) {
            handleZoomSet("-");
        } else {
            handleZoomSet("+");
        }
    };

    // 리스트 터치 조작
    const listRef = useRef(null);
    useEffect(() => {
        const listElement = listRef.current;
    
        let touchStartX;
        let touchStartT;
        let touchStartTarget;
    
        function handleTouchStart(e) {
            touchStartX = e.changedTouches[0].clientX;
            touchStartT = e.timeStamp;
            touchStartTarget = e.target;
        }
    
        function handleTouchEnd(e) {
            const touchEndX = e.changedTouches[0].clientX;
            const touchEndT = e.timeStamp;
            const touchEndTarget = e.target;
            const swipeDistance = touchEndX - touchStartX;
            const swipeTime = touchEndT - touchStartT;
            if (Math.abs(swipeDistance) > 50 && swipeTime < 1000) {
                const limit = listElement.scrollWidth - listElement.clientWidth;
                // 스와이프
                if (listRef && listElement) {
                    if (listElement.contains(touchStartTarget) && listElement.contains(touchEndTarget)) {
                        const updatedlistX = listElement.scrollLeft - swipeDistance;
                        listElement.scrollTo(Math.max(0, Math.min(limit, updatedlistX)), 0);
                    };
                };
            };
        };
    
        function handleWheel(e) {
            const limit = listElement.scrollWidth - listElement.clientWidth;
            // deltaY 값이 양수일 경우 스크롤이 내려가고, 음수일 경우 스크롤이 올라갑니다.
            if (e.deltaY > 0) {
                // 스크롤이 내려갈 때의 동작
                const updatedlistX = listElement.scrollLeft - 100;
                if (updatedlistX < 0) {
                    listElement.scrollLeft = 0;
                } else {
                    listElement.scrollLeft = updatedlistX;
                }
            } else if (e.deltaY < 0) {
                // 스크롤이 올라갈 때의 동작
                const updatedlistX = listElement.scrollLeft + 100;
                if (updatedlistX > limit) {
                    listElement.scrollLeft = limit;
                } else {
                    listElement.scrollLeft = updatedlistX;
                }
            }
        }
    
        if (listElement) {
            listElement.addEventListener("touchstart", handleTouchStart);
            listElement.addEventListener("touchend", handleTouchEnd);
            listElement.addEventListener("wheel", handleWheel);
            window.addEventListener('resize', () => listElement.scrollTo({ left: 0, behavior: 'smooth' }));
        }
    
        return () => {
            if (listElement) {
                listElement.removeEventListener("touchstart", handleTouchStart);
                listElement.removeEventListener("touchend", handleTouchEnd);
                listElement.removeEventListener("wheel", handleWheel);
                window.removeEventListener('resize', () => listElement.scrollTo({ left: 0, behavior: 'smooth' }));
            }
        };
    }, [listRef]);

    function handleSelectSection(index) {
        setSectionX(0);
        setSelectedSection(index);
    };

    function handleCloseModal() {
        setModalContent({
            title: "",
            src: "",
        });
        setZoomPoint({
            x: 0,
            y: 0,
        })
        setZoomLevel(100);
        setShowImgModal(false);
    };

    // 작업물 터치 조작
    const sectionRef = useRef(null);
    useEffect(() => {
        const sectionElement = sectionRef.current;

        let touchStartX;
        let touchStartT;
        let touchStartTarget;

        function handleTouchStart(e) {
            touchStartX = e.changedTouches? e.changedTouches[0].clientX : e.clientX;
            touchStartT = e.timeStamp;
            touchStartTarget = e.target;
        };

        function handleTouchEnd(e) {
            const touchEndX = e.changedTouches? e.changedTouches[0].clientX : e.clientX;
            const touchEndT = e.timeStamp;
            const touchEndTarget = e.target;
            const swipeDistance = touchEndX - touchStartX;
            const swipeTime = touchEndT - touchStartT;
            if (Math.abs(swipeDistance) > 50 && swipeTime < 1000) {
                const limit = sectionElement.scrollWidth - sectionElement.clientWidth;
                // 스와이프
                if (sectionRef && sectionElement) {
                    if (sectionElement.contains(touchStartTarget) && sectionElement.contains(touchEndTarget)) {
                        const updatedsectionX = sectionElement.scrollLeft - swipeDistance;
                        sectionElement.scrollTo(Math.max(0, Math.min(limit, updatedsectionX)), 0);
                    };
                };
            };
        };

        function handleWheel(e) {
            const limit = sectionElement.scrollWidth - sectionElement.clientWidth;
            // deltaY 값이 양수일 경우 스크롤이 내려가고, 음수일 경우 스크롤이 올라갑니다.
            if (e.deltaY > 0) {
                // 스크롤이 내려갈 때의 동작
                const updatedsectionX = sectionElement.scrollLeft - 200;
                if (updatedsectionX < 0) {
                    sectionElement.scrollLeft = 0;
                } else {
                    sectionElement.scrollLeft = updatedsectionX;
                }
            } else if (e.deltaY < 0) {
                // 스크롤이 올라갈 때의 동작
                const updatedsectionX = sectionElement.scrollLeft + 200;
                if (updatedsectionX > limit) {
                    sectionElement.scrollLeft = limit;
                } else {
                    sectionElement.scrollLeft = updatedsectionX;
                }
            };
        };

        if (sectionElement) {
            sectionElement.addEventListener("touchstart", handleTouchStart);
            sectionElement.addEventListener("mousedown", handleTouchStart);
            sectionElement.addEventListener("touchend", handleTouchEnd);
            sectionElement.addEventListener("mouseup", handleTouchEnd);
            sectionElement.addEventListener("wheel", handleWheel);
            window.addEventListener('resize', () => sectionElement.scrollTo({ left: 0, behavior: 'smooth' }));
        }

        return () => {
            if (sectionElement) {
                sectionElement.removeEventListener("touchstart", handleTouchStart);
                sectionElement.removeEventListener("mousedown", handleTouchStart);
                sectionElement.removeEventListener("touchend", handleTouchEnd);
                sectionElement.removeEventListener("mouseup", handleTouchEnd);
                sectionElement.removeEventListener("wheel", handleWheel);
                window.removeEventListener('resize', () => sectionElement.scrollTo({ left: 0, behavior: 'smooth' }));
            }
        };
    }, [sectionRef]);

    function handleMoveImg(type) {
        const indexNum = modalIndexNum;
            if (type === "prev") {
                if (indexNum%10 === 0) {
                    setModalContent({
                        title: workImgs[(indexNum/10 - 1)][workImgs[(indexNum/10 - 1)].length - 1].title,
                        src: workImgs[(indexNum/10 - 1)][workImgs[(indexNum/10 - 1)].length - 1].src,
                        alt: workImgs[(indexNum/10 - 1)][workImgs[(indexNum/10 - 1)].length - 1].alt,
                        indexNum: (indexNum/10 - 1)*10 + workImgs[(indexNum/10 - 1)].length - 1,
                    });
                    setSelectedSection(indexNum/10 - 1);    
                } else {
                    setModalContent({
                        title: workImgs[Math.floor(indexNum / 10)][indexNum%10 - 1].title,
                        src: workImgs[Math.floor(indexNum / 10)][indexNum%10 - 1].src,
                        alt: workImgs[Math.floor(indexNum / 10)][indexNum%10 - 1].alt,
                        indexNum: indexNum - 1,
                    });
                }
            } else if (type === "next") {
                if (indexNum%10 === workImgs[Math.floor(indexNum / 10)].length - 1) {
                    setModalContent({
                        title: workImgs[Math.floor(indexNum / 10) + 1][0].title,
                        src: workImgs[Math.floor(indexNum / 10) + 1][0].src,                
                        alt: workImgs[Math.floor(indexNum / 10) + 1][0].alt,
                        indexNum: (Math.floor(indexNum / 10) + 1)*10,
                    });
                    setSelectedSection(Math.floor(indexNum / 10) + 1);
                } else {
                    setModalContent({
                        title: workImgs[Math.floor(indexNum / 10)][indexNum%10 + 1].title,
                        src: workImgs[Math.floor(indexNum / 10)][indexNum%10 + 1].src,
                        alt: workImgs[Math.floor(indexNum / 10)][indexNum%10 + 1].alt,
                        indexNum: indexNum + 1,
                    });
                }
            };
    };

    useEffect(() => {
        setModalIndexNum(modalContent.indexNum);
    }, [modalContent])

    return (
        <>
            <CS.Container className="siru_wire_frame">
                <CS.Screen>
                <GalleryHeader
                        text='dokdo_wireframe.pdf' 
                        titleRef={titleRef}
                    />
                    <CS.Title 
                        className="title"
                        ref={titleRef}
                    >
                        <h3>독도전시관 반응형 WireFrame</h3>
                        <h3 className="mobile-title">독도전시관<br/> 반응형 WireFrame</h3>
                        <p>
                            독도전시관 웹 페이지의 반응형 디자인을 구상해보았습니다.
                        </p>
                        <p>
                            데스크탑에서 디자인을 바탕으로 모바일 환경에서의
                            디자인을 구상해보며 반응형 디자인에 대해 이해하는 시간을 가졌습니다.
                        </p>
                    </CS.Title>
                    <CS.Content>
                        <CS.SectionGuider 
                            className="works_nav"
                            ref={listRef}
                        >
                            <ul 
                                className="works_list_wrapper"
                            >
                            {sectionData.map((item, index) => (
                                <li 
                                    key={index}
                                    className= {selectedSection===index? "sel" : ""}
                                    onClick={() => handleSelectSection(index)}
                                >
                                    {item}
                                </li>
                            ))}
                            </ul>
                        </CS.SectionGuider>
                        <CS.WorksSection 
                            className="works_section"
                            ref={sectionRef}
                        >
                            {selectedSection === 0 &&
                            <GalleryWorkSection 
                                imgs={workImgs[0]}
                                indexNum={0}
                                setShowImgModal={setShowImgModal}
                                setModalContent={setModalContent}
                                setModalIndexNum={setModalIndexNum}
                            />
                            }
                            {selectedSection === 1 &&
                            <GalleryWorkSection 
                                imgs={workImgs[1]}
                                indexNum={1}
                                setShowImgModal={setShowImgModal}
                                setModalContent={setModalContent}
                                setModalIndexNum={setModalIndexNum}
                            />
                            }
                        </CS.WorksSection>
                    </CS.Content>
                </CS.Screen>
            </CS.Container>
            <Overlay
                className="img_overlay"
                $isShow={showImgModal}
                onClick={handleCloseModal}
            />
            <Modal
                className="img_modal"
                $isShow={showImgModal}
            >
                <h2 className="title">
                    <span>{modalContent.title}.png</span>
                    <button onClick={handleCloseModal}>&times;</button>
                </h2>
                <ModalImgContent 
                    className="modal_img_content"
                    $zoom={zoomLevel}
                >
                    <figure 
                        className="modal_img_wrap" 
                        ref={zoomImgRef}
                        onMouseLeave={() => setTouchStatus(false)}
                    >
                        <img 
                            className="modal_big_img" 
                            alt={modalContent.alt} 
                            src={modalContent.src}
                            onWheel={(e) => handleZoomScroll(e)}
                            style={{
                                top: "50%",
                                left: "50%",
                                transform: `translate(-50%, -50%) translateX(${zoomPoint.x}px) translateY(${zoomPoint.y}px)`,
                            }}
                            draggable="false"
                        />
                    </figure>
                    <div 
                        className="photo_manager"
                    >
                        <button 
                            className="move_button" 
                            onClick={() => handleMoveImg("prev")}
                            disabled={modalIndexNum === 0? true : false}
                            style={{
                                pointerEvents: modalIndexNum === 0 ? "none" : "auto",
                                opacity: modalIndexNum === 0 ? 0.5 : 1,
                            }}
                        >
                            ◀
                        </button>
                        <div className="zoom_manager">
                            <button className="zoom_in_btn" onClick={() => handleZoomSet("+")}>
                                <Icon icon="codicon:zoom-in" />
                            </button>
                            <div 
                                className="zoom_level"
                                style={{
                                    cursor: "zoom-in"
                                }}
                            >{zoomLevel}%</div>
                            <button className="zoom_out_btn" onClick={() => handleZoomSet("-")}>
                                <Icon icon="clarity:zoom-out-line" />
                            </button>
                        </div>
                        <button 
                            className="move_button" 
                            onClick={() => handleMoveImg("next")}
                            disabled={modalIndexNum === 12? true : false}
                            style={{
                                pointerEvents: modalIndexNum === 12 ? "none" : "auto",
                                opacity: modalIndexNum === 12 ? 0.5 : 1,
                            }}
                        >
                            ▶
                        </button>
                    </div>
                </ModalImgContent>
            </Modal>
        </>
    )
};