import React from "react";
import { useEffect, useRef, useState } from "react";
import * as CS from "../components/common/Container";
import * as FS from "../components/common/FolderComps";
import styled from "styled-components";
import Header from "../components/common/Header";
import AI from "../components/common/AI";
import Title from "../components/common/Title";
import { Overlay, Modal } from "../components/modal/modal";
import { Content } from "../components/common/Container";

import { modalData } from "../components/GalleryData";

// 이미지
import Folder from "../asset/folder.png";
import { useNavigate } from "react-router";

const FadeOut = styled.div`
    position: fixed;
    background-color: rgb(250, 250, 250);
    width: 200%;
    height: 200%;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) scale(${props => (props.$fade ? 1 : 0)});
    opacity: ${props => (props.$fade ? 1 : 0)};
    visibility: ${props => (props.$fade ? "visible" : "hidden")};
    transition: all 400ms ease-in-out;
    border-radius: 50%;
    z-index: 2000;
`;

const FadeIn = styled.div`
    position: fixed;
    background-color: rgb(40, 40, 40);
    width: 200%;
    height: 200%;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) scale(${props => (props.$fade ? 1 : 0)});
    opacity: ${props => (props.$fade ? 1 : 0)};
    visibility: ${props => (props.$fade ? "visible" : "hidden")};
    transition: all 400ms ease-in-out;
    border-radius: 50%;
    z-index: 2000;
`;

const titleData = ["works", "gallery"];

const folderData = ["UI/UX", "JavaScripts", "WebPage"];


export default function Gallery() {
    const navigate = useNavigate();
    const [titleStatus, setTitleStatus] = useState(false);
    const nextRef = useRef(null);
    const prevRef = useRef(null);
    const sideRef = useRef(null);
    const [fadeOut, setFadeOut] = useState(false);
    const [fadeIn, setFadeIn] = useState(false);

    // 모달 아이콘(리스트) 관리
    const handleClickIco = (link) => {
        if (link.includes('http')) {
            window.open(link, '_blank'); // 새 탭에서 열기
        } else {
            setFadeOut(true);
            setTimeout(() => {
                setFadeIn(true);
            }, 400);
            setTimeout(() => {
                navigate(`${link}`);
            }, 800);
        }
    };

    // 폴더 관리
    const [selectFolder, setSelectFolder] = useState(-1);
    const folderRefs = useRef(null);
    const [showModal, setShowModal] = useState(-1);

    useEffect(() => {
        function handleClickMouse(e) {
        if (!Object.values(folderRefs).some(ref => ref && ref.contains(e.target))) {
                if (showModal === -1) {
                    setSelectFolder(-1);
                }
            };
        };

        window.addEventListener('click', handleClickMouse);
        return () => {
            window.removeEventListener('click', handleClickMouse);
        }
    }, []);

    const handleClickFolder = (index) => {
        if (selectFolder === index) {
            setShowModal(index);
        } else {
            setSelectFolder(index);
        }
    };

    const handleCloseModal = () => {
        setShowModal(-1);
    };

    return (
        <>
            <CS.Container className="gallery">
                <FadeOut className="fade_out" $fade={fadeOut} />
                <FadeIn className="fade_in" $fade={fadeIn} />
                <CS.Screen>
                    <Header
                        text='gallery' 
                        titleStatus={titleStatus}  
                        nextRef={nextRef}
                        prevRef={prevRef}
                        sideRef={sideRef}
                        nextLink='/'
                        prevLink='/intro'
                    />
                    <FS.FolderList>
                        {folderData.map((item, index) => (
                            <li 
                                key={index} 
                                ref={(e) => folderRefs[index] = e}
                                onClick={() => handleClickFolder(index)}
                            >
                                <figure>
                                    <img src={Folder} alt={item}/>
                                    <FS.FolderInner 
                                        id="inner" 
                                        className={selectFolder === index? "sel" : "" }
                                        style={{
                                            top: showModal === index? "-400%" : "20%",
                                        }}
                                    />
                                    <FS.FolderInner 
                                        id="case"
                                        className={selectFolder === index? "sel" : "" }
                                    />
                                </figure>
                                <p>{item.toUpperCase()}</p>
                            </li>
                        ))}
                    </FS.FolderList>
                    <Content>
                        <AI 
                            titleStatus={titleStatus} 
                            mes="works"
                            nextRef={nextRef}
                            prevRef={prevRef}
                            sideRef={sideRef}
                        />
                        <Title 
                            titleData={titleData} 
                            titleStatus={titleStatus} 
                            setTitleStatus={setTitleStatus}
                        />
                    </Content>
                </CS.Screen>
                {folderData.map((item, index) => (
                <React.Fragment key={index}>
                    <Overlay $isShow = {showModal === index} onClick={handleCloseModal}/>
                    <Modal $isShow = {showModal === index}>
                        <h2 className="title">
                            <span>{item}</span>
                            <button onClick={handleCloseModal}>&times;</button>
                        </h2>
                        <FS.FolderContent>
                        {modalData && modalData[index] && modalData[index].map((modalItem, modalIndex) => (
                            <li 
                                key={modalIndex}
                                onClick={() => handleClickIco(modalItem.link)}
                            >
                                <img src={modalItem.ico} alt={modalItem.alt} />
                                <p>{modalItem.title}</p>
                            </li>
                        ))}
                        </FS.FolderContent>
                    </Modal>
                </React.Fragment>
                ))}
            </CS.Container>
        </>
    )
};