export default function GalleryWorkSection({ imgs, setShowImgModal, setModalContent, indexNum }) {

  function handleOpenImgModal(indexNum, index) {
    setModalContent({
      title: imgs[index].title,
      src: imgs[index].src,
      alt: imgs[index].alt,
      indexNum: indexNum*10 + index,
    });
    setShowImgModal(true);
  };

  return (
    <>
        <div 
            className="works_content"
        >
          {imgs.map((item, index) => (
            <img 
              src={item.src} 
              key={index} 
              alt={item.alt}
              onClick={() => handleOpenImgModal(indexNum, index)}
              draggable="false"
            />
          ))}
        </div>
    </>
  )
}