export default function Header({ text, titleStatus, nextRef, prevRef, nextLink, prevLink, sideRef }) {
    const navigate = useNavigate();
    const location = useLocation();
    const [fadeOut, setFadeOut] = useState(false);
    const [sideShow, setSideShow] = useState(false);

    const isRootPath = location.pathname === '/';
    const isLastPath = location.pathname === '/gallery';

    useEffect(() => {
        let touchStartX;
        let touchStartT;

        function handleTouchStart(e) {
            touchStartX = e.touches[0].clientX;
            touchStartT = e.timeStamp;
        }

        function handleTouchEnd(e) {
            const touchEndX = e.changedTouches[0].clientX;
            const touchEndT = e.timeStamp;
            const swipeDistance = touchEndX - touchStartX;
            const swipeTime = touchEndT - touchStartT;
            // 일정 거리와 시간 이하로 움직였을 때 스와이프로 판단
            if (Math.abs(swipeDistance) > 50 && swipeTime < 1000) {
                if (swipeDistance > 0) {
                    // 오른쪽 스와이프
                    if (!isRootPath) {
                        handleLink("prev");
                    };
                } else {
                    // 왼쪽 스와이프
                    if (!isLastPath) {
                        handleLink("next");
                    }
                }
            }
        };

        window.addEventListener("touchstart", handleTouchStart);
        window.addEventListener("touchend", handleTouchEnd);
        return () => {
            window.removeEventListener("touchstart", handleTouchStart);
            window.removeEventListener("touchend", handleTouchEnd);
        }
    }, [titleStatus]);

    function handleLink(type) {
        if (titleStatus) {
            setFadeOut(true);
            setTimeout(() => {
                if (type === "prev") {
                    navigate(`${prevLink}`);
                } else if (type === "next") {
                    navigate(`${nextLink}`);
                }
            }, 400);
        }
    };
    
    // 사이드바 관리
    const [galleryListView, setGalleryListView] = useState(false);
    const [galleryUIUXListView, setGalleryUIUXListView] = useState(false);
    const [galleryJSListView, setGalleryJSListView] = useState(false);
    const [galleryWEBListView, setGalleryWEBListView] = useState(false);

    function handelSideShow() {
        setSideShow(!sideShow);
    };

    return (
        <>
        <FadeOut className="fade_out" $fade={fadeOut} />
        <Container>
            <Detail>
                <p>YEAR</p>
                <p>2025</p>
            </Detail>
            <Title>
                <p>{text.toUpperCase()}</p>
                <div className="nav_buttons">
                    {!isRootPath &&
                    <LinkBtn 
                        onClick={() => handleLink("prev")}
                        ref={prevRef}
                        className={titleStatus? "act" : ""}
                        disabled={!titleStatus}
                    >
                        ←
                    </LinkBtn>
                    }
                    {!isLastPath &&
                    <LinkBtn 
                        onClick={() => handleLink("next")}
                        ref={nextRef}
                        className={titleStatus? "act" : ""}
                        disabled={!titleStatus}
                    >
                        →
                    </LinkBtn>
                    }
                    <FastLinkBtn
                        onClick={handelSideShow}
                        ref={sideRef}
                        className={titleStatus? "act" : ""}
                        disabled={!titleStatus}
                    >
                        <Icon icon="healthicons:ui-menu-outline" />
                    </FastLinkBtn>
                </div>
            </Title>
            <FastLink
                $isShow={sideShow}
            >
                <li>
                    <Link to='/'>HOME</Link>
                </li>
                <li>
                    <Link to='/intro'>INTRO</Link>
                </li>
                <li>
                    <Link to='/gallery'>GALLERY</Link>
                </li>                                
            </FastLink>
        </Container>
        </>
    )
};